381	     * The reason a claim is voided with: none while the sheet's list of void reasons is empty, else the one given,
382	     * which must be on the list.
383	     */
384	    private String requireVoidReason(String sheetId, Long id, String given) {
385	        List<String> listed = voidReasons.list(sheetId).stream().map(VoidReason::getReason).toList();
386	        if (listed.isEmpty()) {
387	            return null;
388	        }
389	        String reason = given == null ? "" : given.trim();
390	        if (reason.isEmpty()) {
391	            throw new ClaimVoidReasonException(id, "choose a reason from the sheet's void reasons");
392	        }
