    /** The rate step with {@code asOf} standing in for the sheet's today. */
    public BigDecimal rateStep(BigDecimal amount, BigDecimal pct, LocalDate roundingDate, LocalDate asOf) {
        return amount.multiply(pct).movePointLeft(2).setScale(2, rounding(roundingDate, asOf));
    }

    /**
     * The late charge on a figure of an OPEN claim dated {@code date}: for every full 30 days the sheet's today is past
     * the claim's due-by, the late percent in force on that boundary (the due-by plus 30, 60, 90 ... days) of the
     * figure plus the charges of the boundaries before it (compounding), each rounded as the claim's date has it,
     * added up; zero when not overdue, null (n/a) when the figure is.
     */
    public BigDecimal lateCharge(BigDecimal figure, LocalDate dueBy, LocalDate date) {
        return lateCharge(figure, dueBy, date, today);
    }

    /** The late charge with {@code asOf} standing in for the sheet's today. */
    public BigDecimal lateCharge(BigDecimal figure, LocalDate dueBy, LocalDate date, LocalDate asOf) {
        if (figure == null) {
            return null;
        }
        long overdueDays = ChronoUnit.DAYS.between(dueBy, asOf);
        long periods = overdueDays <= 0 ? 0 : overdueDays / 30;
        BigDecimal charge = BigDecimal.ZERO.setScale(2);
        for (long boundary = 1; boundary <= periods; boundary++) {
            charge = charge.add(figure.add(charge).multiply(latePctOn(dueBy.plusDays(30 * boundary))).movePointLeft(2)
                    .setScale(2, rounding(date, asOf)));
        }
        return charge;
    }

    /** The figure with its late charge added on top when the claim is OPEN; null (n/a) stays null. */
    public BigDecimal withLateCharge(BigDecimal figure, boolean open, LocalDate dueBy, LocalDate date) {
        return withLateCharge(figure, open, dueBy, date, today);
    }

    /** The figure with its late charge, with {@code asOf} standing in for the sheet's today. */
    public BigDecimal withLateCharge(BigDecimal figure, boolean open, LocalDate dueBy, LocalDate date,
            LocalDate asOf) {
        return figure == null || !open ? figure : figure.add(lateCharge(figure, dueBy, date, asOf));
    }

    /** A due-total held down to the cap in force on the sheet's today; null (n/a), or no cap, leaves it as it is. */
    public BigDecimal capped(BigDecimal dueTotal) {
        return capped(dueTotal, today);
    }

    /** A due-total held down to the cap in force on {@code asOf}, standing in for the sheet's today. */
    public BigDecimal capped(BigDecimal dueTotal, LocalDate asOf) {
        BigDecimal cap = decimalOn(CAP, asOf).orElse(null);
        return dueTotal == null || cap == null ? dueTotal : dueTotal.min(cap);
    }

    /** A live due of a claim dated on the date raised to the floor in force on it; null (n/a) stays null. */
    public BigDecimal floored(BigDecimal due, LocalDate date) {
        return due == null ? null : due.max(floorOn(date));
    }
}
package net.officefloor.hq.app.sheet;


/**
 * Loads a sheet by id, starting an empty one the first time the id is used, and keeps the sheet's
 * today. The real clock is read only once, to give a new sheet its starting today; everything else
 * dated uses {@link #today(String)}.
 */
@Service
public class SheetService {

    private final SheetRepository sheets;
    private final RollupService rollup;
    private final PeriodService periods;
    private final RoleService roles;
    private final Audit audit;
    private final ClaimRepository claims;

    public SheetService(SheetRepository sheets, RollupService rollup, PeriodService periods, RoleService roles,
            Audit audit, ClaimRepository claims) {
        this.claims = claims;
        this.sheets = sheets;
        this.rollup = rollup;
        this.periods = periods;
        this.roles = roles;
        this.audit = audit;
    }

    public Sheet load(String id, String user) {
        return sheets.findById(id).orElseGet(() -> start(id, user));
    }

    /** Whether the user is a viewer of the sheet, who may change nothing. */
    public boolean isViewer(String id, String user) {
        return roles.isViewer(id, user);
    }

    public Sheet get(String id) {
        return sheets.findById(id).orElseThrow(() -> new SheetNotFoundException(id));
    }

    /** The sheet's today: use it for every date-dependent decision and default date. */
    public LocalDate today(String id) {
        return sheets.findById(id).map(Sheet::getToday).orElseThrow(() -> new SheetNotFoundException(id));
    }

    /** The default date of a new claim: the sheet's entry date while it is set, else its today. */
    public LocalDate entryDate(String id) {
        return get(id).entryDateOrToday();
    }

    /** Whether the sheet is archived: every change to it is refused. A sheet not started yet is not. */
    public boolean isArchived(String id) {
        return sheets.findById(id).map(Sheet::isArchived).orElse(false);
    }

    /** Archive the sheet: only a steward may, and only once. */
    @Transactional
    public Sheet archive(String id, String user) {
        Sheet sheet = sheets.findById(id).orElseThrow(() -> new SheetNotFoundException(id));
        if (sheet.isArchived()) {
            throw new SheetArchivedException(id);
        }
        if (roles.roleOf(id, user) != Role.STEWARD) {
            throw new ArchiveForbiddenException(id, user);
        }
        sheet.setArchived(true);
        Sheet saved = sheets.saveAndFlush(sheet);
        audit.recordOnCommit("SHEET_ARCHIVED sheet=" + id + " by=" + user);
        return saved;
    }

    /**
     * Change the sheet's today. A change first records a SNAPSHOT of each person's due-total on the day being left,
     * in list order; every open period past its grace days on the new today then closes, before the figures it moved
     * are recorded. A new today releases every claim editor's lock.
     */
    @Transactional
    public Sheet setToday(String id, String user, LocalDate today) {
        Sheet sheet = sheets.findById(id).orElseThrow(() -> new SheetNotFoundException(id));
        RollupService.Snapshot before = rollup.snapshot(id);
        boolean changed = !today.equals(sheet.getToday());
        if (changed) {
            before.people().values().forEach(person -> audit.recordOnCommit("SNAPSHOT sheet=" + id + " by=" + user
                    + " name=" + person.name() + " due-total=" + person.dueTotal()));
        }
        sheet.setToday(today);
        Sheet saved = sheets.saveAndFlush(sheet);
        periods.autoClose(id, user, today, saved.getGraceDays());
        rollup.recordChanges(id, user, before);
        if (changed) {
            claims.unlockAll(id);
        }
        return saved;
    }

    /**
     * The next claim number on the sheet: 1 for the first, then 2, and so on. The sheet's row is
     * locked until the caller's transaction ends, so two claims opened at once get different numbers.
     */
    @Transactional
    public long nextClaimNumber(String id) {
        if (sheets.incrementLastClaimNumber(id) != 1) {
            throw new SheetNotFoundException(id);
        }
        return sheets.lastClaimNumber(id);
    }

    /**
     * The next bulk settle batch number on the sheet: 1 for the first, then 2, and so on. The sheet's row is locked
     * until the caller's transaction ends, so a batch whose claims all roll back takes no number.
     */
    @Transactional
    public long nextSettleBatch(String id) {
        if (sheets.incrementLastSettleBatch(id) != 1) {
            throw new SheetNotFoundException(id);
        }
        return sheets.lastSettleBatch(id);
    }

    /** The number of the sheet's last bulk settle batch, as stored now: 0 while there has been none. */
    public long lastSettleBatch(String id) {
        return sheets.lastSettleBatch(id);
    }

    /**
     * The next place in the sheet's claim lists: a claim with a later place is listed before one with an earlier
     * place. The sheet's row is locked until the caller's transaction ends.
     */
    @Transactional
    public long nextListed(String id) {
        if (sheets.incrementLastListed(id) != 1) {
            throw new SheetNotFoundException(id);
        }
        return sheets.lastListed(id);
    }

    /**
     * The next number in a sequence of its own on the sheet (a period's, or X for no period): the key, a dash, then
     * 1 for the first, then 2, and so on. The sheet's row is locked until the caller's transaction ends.
     */
    @Transactional
    public String nextSequenceNumber(String id, String key) {
        if (sheets.lockById(id) != 1) {
            throw new SheetNotFoundException(id);
        }
        sheets.incrementSequence(id, key);
        return key + "-" + sheets.lastSequenceNumber(id, key);
    }

    private Sheet start(String id, String user) {
        try {
            return sheets.saveAndFlush(new Sheet(id, user, LocalDate.now()));
        } catch (DataIntegrityViolationException e) {
            // Another user started the same sheet at the same moment: it exists now.
            return sheets.findById(id).orElseThrow(() -> e);
        }
    }
}

package net.officefloor.hq.app.rollup;


/**
 * Works out each person's claimed, due-total and overdue-total and the sheet's totals as the screen shows them, so a change can
 * record in the audit whose figures it moved. Take a {@link #snapshot(String)} before the change, then call
 * {@link #recordChanges(String, String, Snapshot)} after its own audit records.
 */
@Service
public class RollupService {

    /**
     * A person's figures as shown: claimed with two decimals, due-total (held down to the cap) with two decimals or
     * n/a, and overdue-total (the dues of their overdue claims) with two decimals.
     */
    public record Figures(String name, String claimed, String dueTotal, String overdueTotal) {
    }

    /** Everyone's figures, by person id in the order they were added, and the sheet's totals. */
    public record Snapshot(Map<Long, Figures> people, String claimedTotal, String dueTotal, String overdueTotal) {
    }

    private final PersonRepository people;
    private final ClaimRepository claims;
    private final ClaimLogRepository logs;
    private final RateRepository rates;
    private final SheetRepository sheets;
    private final Audit audit;

    public RollupService(PersonRepository people, ClaimRepository claims, ClaimLogRepository logs,
            RateRepository rates, SheetRepository sheets, Audit audit) {
        this.people = people;
        this.claims = claims;
        this.logs = logs;
        this.rates = rates;
        this.sheets = sheets;
        this.audit = audit;
    }

    /** The sheet's figures now; empty when the sheet does not exist. */
    public Snapshot snapshot(String sheetId) {
        Sheet sheet = sheets.findById(sheetId).orElse(null);
        LocalDate today = sheet == null ? null : sheet.getToday();
        List<Rate> sheetRates = rates.findBySheetIdOrderByGradeAscFromDateAscIdAsc(sheetId);
        Map<Long, List<Claim>> counted = new LinkedHashMap<>();
        for (Claim claim : claims.findBySheetIdOrderByIdDesc(sheetId)) {
            if (claim.getStatus().counts()) {
                counted.computeIfAbsent(claim.getPersonId(), id -> new ArrayList<>()).add(claim);
            }
        }
        Map<Long, Figures> figures = new LinkedHashMap<>();
        BigDecimal claimedTotal = zero();
        List<BigDecimal> dues = new ArrayList<>();
        List<BigDecimal> overdues = new ArrayList<>();
        for (Person person : people.findBySheetIdOrderByIdAsc(sheetId)) {
            List<Claim> theirs = counted.getOrDefault(person.getId(), List.of()).stream()
                    .filter(claim -> person.counts(claim, today))
                    .toList();
            BigDecimal claimed = zero();
            BigDecimal due = zero();
            BigDecimal overdue = zero();
            boolean anyDue = today != null && rateOn(sheetRates, person.gradeOn(today), today).isPresent();
            for (Claim claim : theirs) {
                claimed = claimed.add(claim.getAmount());
                if (claim.getSettledDue() != null || claim.getBoundDue() != null) {
                    anyDue = true;
                }
                Optional<BigDecimal> claimDue = dueOf(sheet, sheetRates, person, claim);
                if (claimDue.isPresent()) {
                    due = due.add(claimDue.get());
                    if (isOverdue(sheet, person, claim, today)) {
                        overdue = overdue.add(claimDue.get());
                    }
                    // A due under a grade the person had on an earlier date counts too.
                    if (today != null && !claim.getDate().isAfter(today)) {
                        anyDue = true;
                    }
                }
            }
            claimedTotal = claimedTotal.add(claimed);
            overdues.add(overdue);
            if (anyDue && sheet != null) {
                due = sheet.capped(due);
            }
            if (anyDue) {
                dues.add(due);
            }
            figures.put(person.getId(), new Figures(person.getName(), shown(claimed), anyDue ? shown(due) : "n/a",
                    shown(overdue)));
        }
        return new Snapshot(figures, shown(claimedTotal), shown(trimmedSum(dues)), shown(trimmedSum(overdues)));
    }

    /** How many claims a candidate rate would change the due of, and the sum of new due minus current due (two decimals). */
    public record RatePreview(int count, String diff) {
    }

    /**
     * What the screen would show if the grade had the percent on every date, changing nothing: of the OPEN and PENDING
     * claims whose person had the grade on the claim's date, how many would show a different due, and the sum of each
     * new due minus its current one (an n/a due counting as 0.00). A claim bound by a statement keeps its stated due.
     */
    public RatePreview preview(String sheetId, String grade, BigDecimal pct) {
        Sheet sheet = sheets.findById(sheetId).orElse(null);
        List<Rate> sheetRates = rates.findBySheetIdOrderByGradeAscFromDateAscIdAsc(sheetId);
        List<Rate> candidate = new ArrayList<>(sheetRates.stream().filter(r -> !r.getGrade().equals(grade)).toList());
        candidate.add(new Rate(sheetId, grade, null, pct));
        Map<Long, Person> byId = new LinkedHashMap<>();
        for (Person person : people.findBySheetIdOrderByIdAsc(sheetId)) {
            byId.put(person.getId(), person);
        }
        int count = 0;
        BigDecimal diff = zero();
        for (Claim claim : claims.findBySheetIdOrderByIdDesc(sheetId)) {
            Person person = byId.get(claim.getPersonId());
            if (person == null || !claim.getStatus().isOpen() || !grade.equals(person.gradeOn(claim.getDate()))) {
                continue;
            }
            BigDecimal now = dueOf(sheet, sheetRates, person, claim).map(RollupService::cents).orElse(null);
            BigDecimal then = dueOf(sheet, candidate, person, claim).map(RollupService::cents).orElse(null);
            if (Objects.equals(now, then)) {
                continue;
            }
            count++;
            diff = diff.add(then == null ? zero() : then).subtract(now == null ? zero() : now);
        }
        return new RatePreview(count, shown(diff));
    }

    private static BigDecimal cents(BigDecimal value) {
        return value.setScale(2, RoundingMode.HALF_EVEN);
    }

    /** The figures added up, leaving out the single highest and the single lowest when there are three or more. */
    private static BigDecimal trimmedSum(List<BigDecimal> figures) {
        List<BigDecimal> kept = new ArrayList<>(figures);
        if (kept.size() >= 3) {
            kept.sort(null);
            kept = kept.subList(1, kept.size() - 1);
        }
        return kept.stream().reduce(zero(), BigDecimal::add);
    }

    /**
     * Each person's due-total of the dates from and to, both inclusive, by person id for every person on the sheet, as
     * the screen shows a person's for a period: the dues as shown now of their claims due by a date in them that were OPEN,
     * PENDING or SETTLED at the end of the to-date by their status log, skipping those with no due and the open ones a
     * hold of theirs leaves out; 0.00 with none.
     */
    public Map<Long, BigDecimal> dueTotalsBetween(String sheetId, LocalDate from, LocalDate to) {
        Sheet sheet = sheets.findById(sheetId).orElse(null);
        LocalDate today = sheet == null ? null : sheet.getToday();
        List<Rate> sheetRates = rates.findBySheetIdOrderByGradeAscFromDateAscIdAsc(sheetId);
        Map<Long, Person> byId = new LinkedHashMap<>();
        Map<Long, BigDecimal> totals = new LinkedHashMap<>();
        for (Person person : people.findBySheetIdOrderByIdAsc(sheetId)) {
            byId.put(person.getId(), person);
            totals.put(person.getId(), zero());
        }
        Map<Long, List<ClaimLog>> logOf = new LinkedHashMap<>();
        for (ClaimLog line : logs.findBySheetIdOrderByIdAsc(sheetId)) {
            logOf.computeIfAbsent(line.getClaimId(), id -> new ArrayList<>()).add(line);
        }
        for (Claim claim : claims.findBySheetIdOrderByIdDesc(sheetId)) {
            Person person = byId.get(claim.getPersonId());
            ClaimStatus status = statusOn(claim, logOf.getOrDefault(claim.getId(), List.of()), to);
            if (person == null || !person.countsAsOf(claim, status, today) || claim.getDueBy().isBefore(from)
                    || claim.getDueBy().isAfter(to)) {
                continue;
            }
            dueOf(sheet, sheetRates, person, claim).ifPresent(due -> totals.merge(person.getId(), due, BigDecimal::add));
        }
        totals.replaceAll((id, total) -> total.setScale(2, RoundingMode.HALF_EVEN));
        return totals;
    }

    /**
     * Record, once the transaction commits, a ROLLUP line for each person whose figures moved since the snapshot (a
     * person new since then counting as moved), then a TOTALS line when any of the sheet's three totals moved.
     */
    public void recordChanges(String sheetId, String user, Snapshot before) {
        Snapshot after = snapshot(sheetId);
        for (Map.Entry<Long, Figures> entry : after.people().entrySet()) {
            Figures was = before.people().get(entry.getKey());
            Figures now = entry.getValue();
            if (was != null && was.claimed().equals(now.claimed()) && was.dueTotal().equals(now.dueTotal())
                    && was.overdueTotal().equals(now.overdueTotal())) {
                continue;
            }
            audit.recordOnCommit("ROLLUP sheet=" + sheetId + " by=" + user + " person=" + now.name()
                    + " claimed=" + now.claimed() + " due-total=" + now.dueTotal()
                    + " overdue-total=" + now.overdueTotal());
        }
        if (!Objects.equals(before.claimedTotal(), after.claimedTotal())
                || !Objects.equals(before.dueTotal(), after.dueTotal())
                || !Objects.equals(before.overdueTotal(), after.overdueTotal())) {
            audit.recordOnCommit("TOTALS sheet=" + sheetId + " by=" + user + " claimed-total=" + after.claimedTotal()
                    + " due-total=" + after.dueTotal() + " overdue-total=" + after.overdueTotal());
        }
    }

    /**
     * As on the screen: the settled due, else the figure (the stated due, else the amount at the rate on the claim's
     * date, rounded as the sheet's policy date has the claim round) with the late charge of an overdue claim added on
     * top, raised last to the floor in force on the claim's date; a correction has neither floor nor late charge.
     */
    private static Optional<BigDecimal> dueOf(Sheet sheet, List<Rate> sheetRates, Person person, Claim claim) {
        if (claim.getSettledDue() != null) {
            return Optional.of(claim.getSettledDue());
        }
        Optional<BigDecimal> figure = claim.isBound() ? Optional.ofNullable(claim.getStatedDue())
                : rateOn(sheetRates, person.gradeOn(claim.getDate()), claim.getDate())
                        .map(Rate::getPct)
                        .map(pct -> sheet == null
                                ? claim.getAmount().multiply(pct).movePointLeft(2).setScale(2, RoundingMode.HALF_EVEN)
                                : sheet.rateStep(claim.getAmount(), pct, claim.getRoundingDate()));
        return sheet == null || claim.isCorrection() ? figure
                : figure.map(f -> sheet.floored(sheet.withLateCharge(f, claim.getStatus().isOpen(),
                        sheet.overdueBy(claim.getDueBy(), person.gradeOn(claim.getDate()), claim.getDate()),
                        claim.getDate()), claim.getDate()));
    }

    /**
     * The status the claim had at the end of the date by its log (oldest first): its last line logged on or before the
     * date; null when it has lines but none by then. With no log at all, its status now.
     */
    private static ClaimStatus statusOn(Claim claim, List<ClaimLog> log, LocalDate date) {
        if (log.isEmpty()) {
            return claim.getStatus();
        }
        ClaimStatus found = null;
        for (ClaimLog line : log) {
            if (!line.getDate().isAfter(date)) {
                found = line.getStatus();
            }
        }
        return found;
    }

    /**
     * As on the screen: an OPEN or PENDING claim whose due-by, plus the grace days its person's grade has on its date,
     * is before the sheet's today.
     */
    private static boolean isOverdue(Sheet sheet, Person person, Claim claim, LocalDate today) {
        return claim.getStatus().isOpen() && today != null && claim.getDueBy() != null
                && sheet.overdueBy(claim.getDueBy(), person.gradeOn(claim.getDate()), claim.getDate()).isBefore(today);
    }

    private static Optional<Rate> rateOn(List<Rate> sheetRates, String grade, LocalDate date) {
        return sheetRates.stream()
                .filter(r -> r.getGrade().equals(grade))
                .filter(r -> r.getFromDate() == null || !r.getFromDate().isAfter(date))
                .max(Comparator.comparing(Rate::getFromDate, Comparator.nullsFirst(Comparator.naturalOrder())))
                .filter(r -> r.appliesOn(date));
    }

    private static BigDecimal zero() {
        return BigDecimal.ZERO.setScale(2);
    }

    private static String shown(BigDecimal value) {
        return value.setScale(2, RoundingMode.HALF_EVEN).toPlainString();
    }
}
package net.officefloor.hq.app.claim;


/** The people's claims on a sheet. The signed-in user's name travels in the {@code X-User} header. */
@RestController
@RequestMapping("/api/sheets/{sheetId}")
@Validated
public class ClaimController {

    /**
     * A claim as shown: the amount with two decimals, the date as yyyy-mm-dd, and the due fixed when it was
     * settled (null when it has none, so its due is worked out from the current rate), and who opened it;
     * whether the person's last statement bound it, and the due it bound it to (null: none, so n/a); and the number of
     * the claim it corrects (null unless it is a correction); and the date that decides how its live figures round (its
     * own, or a correction's corrected claim's); and its place in its person's list (a later place listed first); and
     * its status log, oldest first; and the date it is deferred until (null when never deferred); and how many proofs
     * it has; and the number of the claim it was split off (null unless it was); and the user whose open editor locks
     * it (null when not locked); and the last day it was reminded (null when never); and its external reference (null
     * when it has none); and its tags, sorted and comma separated (null when it has none); and the reason it was voided
     * with (null when none); and its comments, oldest first; and the bulk settle batch that settled it (null when none).
     */
    public record ClaimView(Long id, Long personId, String amount, LocalDate date, String note, ClaimStatus status,
            String number, String settledDue, String openedBy, boolean stated, String statedDue, String corrects,
            LocalDate roundingDate, long listed, LocalDate dueBy, List<ClaimLogView> log, LocalDate deferredUntil,
            int proofs, String splitFrom, String lockedBy, boolean lateEntry, LocalDate remindedOn, String ref,
            String tags, String voidReason, List<ClaimCommentView> comments, Long settleBatch) {

        /** A claim with no comments yet. */
        static ClaimView of(Claim claim, List<ClaimLog> log) {
            return of(claim, log, List.of());
        }

        static ClaimView of(Claim claim, List<ClaimLog> log, List<ClaimComment> comments) {
            return new ClaimView(claim.getId(), claim.getPersonId(),
                    claim.getAmount().setScale(2, RoundingMode.UNNECESSARY).toPlainString(),
                    claim.getDate(), claim.getNote(), claim.getStatus(), claim.getNumber(),
                    claim.getSettledDue() == null ? null : claim.getSettledDue().toPlainString(),
                    claim.getOpenedBy(), claim.isStated(),
                    claim.getStatedDue() == null ? null : claim.getStatedDue().toPlainString(),
                    claim.getCorrects(), claim.getRoundingDate(), claim.getListed(), claim.getDueBy(),
                    log.stream().map(ClaimLogView::of).toList(), claim.getDeferredUntil(),
                    claim.getProofs(), claim.getSplitFrom(), claim.getLockedBy(),
                    claim.isLateEntry(), claim.getRemindedOn(), claim.getRef(),
                    claim.getTags(), claim.getVoidReason(),
                    comments.stream().map(ClaimCommentView::of).toList(), claim.getSettleBatch());
        }
    }

    /** A comment on a claim: who wrote it, the sheet's today then, and its text. */
    public record ClaimCommentView(String by, LocalDate date, String text) {

        static ClaimCommentView of(ClaimComment comment) {
            return new ClaimCommentView(comment.getBy(), comment.getDate(), comment.getText());
        }
    }

    /** A line of a claim's status log: the status, who changed it, the sheet's today then, and its due then (or n/a). */
    public record ClaimLogView(ClaimStatus status, String by, LocalDate date, String due) {

        static ClaimLogView of(ClaimLog line) {
            return new ClaimLogView(line.getStatus(), line.getBy(), line.getDate(), line.getDue());
        }
    }

    /**
     * An amount with up to two decimals, negative only for a correction; a missing date takes the sheet's today; the
     * number of the claim a correction corrects, blank for any other claim; an external reference, blank for none;
     * comma separated tags, blank for none.
     */
    public record ClaimRequest(
            @NotNull @Pattern(regexp = "\\s*-?\\d{1,10}(\\.\\d{1,2})?\\s*") String amount,
            LocalDate date,
            @Size(max = 1000) String note,
            @Size(max = 255) String corrects,
            @Size(max = 255) String ref,
            @Size(max = 1000) String tags) {

        BigDecimal amountValue() {
            return new BigDecimal(amount.trim()).setScale(2, RoundingMode.UNNECESSARY);
        }

        String correctsValue() {
            if (corrects == null || corrects.isBlank()) {
                return null;
            }
            // A sheet-wide number is written without leading zeros; a period number (P1-1, X-1) as typed.
            String trimmed = corrects.trim();
            return trimmed.matches("\\d{1,18}") ? String.valueOf(Long.parseLong(trimmed)) : trimmed;
        }
    }

    /** The ids of the claims selected to open together. */
    public record BulkOpenRequest(@NotNull @Size(max = 10000) List<@NotNull Long> ids) {
    }

    /** The ids of the claims selected to move together, and the person they are moved to. */
    public record BulkReassignRequest(@NotNull @Size(max = 10000) List<@NotNull Long> ids, @NotNull Long personId) {
    }

    /** The ids of the claims selected to settle together. */
    public record BulkSettleRequest(@NotNull @Size(max = 10000) List<@NotNull Long> ids) {
    }

    /** Lines of name,amount,date,note to add as DRAFT claims. */
