1	package net.officefloor.hq.app.rollup;
2	
3	
4	/**
5	 * Works out each person's claimed, due-total and overdue-total and the sheet's totals as the screen shows them, so a change can
6	 * record in the audit whose figures it moved. Take a {@link #snapshot(String)} before the change, then call
7	 * {@link #recordChanges(String, String, Snapshot)} after its own audit records.
8	 */
9	@Service
10	public class RollupService {
11	
12	    /**
13	     * A person's figures as shown: claimed with two decimals, due-total (held down to the cap) with two decimals or
14	     * n/a, and overdue-total (the dues of their overdue claims) with two decimals.
15	     */
16	    public record Figures(String name, String claimed, String dueTotal, String overdueTotal) {
17	    }
18	
19	    /** Everyone's figures, by person id in the order they were added, and the sheet's totals. */
20	    public record Snapshot(Map<Long, Figures> people, String claimedTotal, String dueTotal, String overdueTotal) {
21	    }
22	
23	    private final PersonRepository people;
24	    private final ClaimRepository claims;
25	    private final ClaimLogRepository logs;
26	    private final RateRepository rates;
27	    private final SheetRepository sheets;
28	    private final Audit audit;
29	
30	    public RollupService(PersonRepository people, ClaimRepository claims, ClaimLogRepository logs,
31	            RateRepository rates, SheetRepository sheets, Audit audit) {
32	        this.people = people;
33	        this.claims = claims;
34	        this.logs = logs;
35	        this.rates = rates;
36	        this.sheets = sheets;
37	        this.audit = audit;
38	    }
39	
40	    /** The sheet's figures now; empty when the sheet does not exist. */
41	    public Snapshot snapshot(String sheetId) {
42	        Sheet sheet = sheets.findById(sheetId).orElse(null);
43	        LocalDate today = sheet == null ? null : sheet.getToday();
44	        List<Rate> sheetRates = rates.findBySheetIdOrderByGradeAscFromDateAscIdAsc(sheetId);
45	        Map<Long, List<Claim>> counted = new LinkedHashMap<>();
46	        for (Claim claim : claims.findBySheetIdOrderByIdDesc(sheetId)) {
47	            if (claim.getStatus().counts()) {
48	                counted.computeIfAbsent(claim.getPersonId(), id -> new ArrayList<>()).add(claim);
49	            }
50	        }
51	        Map<Long, Figures> figures = new LinkedHashMap<>();
52	        BigDecimal claimedTotal = zero();
53	        List<BigDecimal> dues = new ArrayList<>();
54	        List<BigDecimal> overdues = new ArrayList<>();
55	        for (Person person : people.findBySheetIdOrderByIdAsc(sheetId)) {
56	            List<Claim> theirs = counted.getOrDefault(person.getId(), List.of()).stream()
57	                    .filter(claim -> person.counts(claim, today))
58	                    .toList();
59	            BigDecimal claimed = zero();
60	            BigDecimal due = zero();
61	            BigDecimal overdue = zero();
62	            boolean anyDue = today != null && rateOn(sheetRates, person.gradeOn(today), today).isPresent();
63	            for (Claim claim : theirs) {
64	                claimed = claimed.add(claim.getAmount());
65	                if (claim.getSettledDue() != null || claim.getBoundDue() != null) {
66	                    anyDue = true;
67	                }
68	                Optional<BigDecimal> claimDue = dueOf(sheet, sheetRates, person, claim);
69	                if (claimDue.isPresent()) {
70	                    due = due.add(claimDue.get());
71	                    if (isOverdue(sheet, person, claim, today)) {
72	                        overdue = overdue.add(claimDue.get());
73	                    }
74	                    // A due under a grade the person had on an earlier date counts too.
75	                    if (today != null && !claim.getDate().isAfter(today)) {
76	                        anyDue = true;
77	                    }
78	                }
79	            }
80	            claimedTotal = claimedTotal.add(claimed);
81	            overdues.add(overdue);
82	            if (anyDue && sheet != null) {
83	                due = sheet.capped(due);
84	            }
85	            if (anyDue) {
86	                dues.add(due);
87	            }
88	            figures.put(person.getId(), new Figures(person.getName(), shown(claimed), anyDue ? shown(due) : "n/a",
89	                    shown(overdue)));
90	        }
91	        return new Snapshot(figures, shown(claimedTotal), shown(trimmedSum(dues)), shown(trimmedSum(overdues)));
92	    }
93	
94	    /** How many claims a candidate rate would change the due of, and the sum of new due minus current due (two decimals). */
95	    public record RatePreview(int count, String diff) {
96	    }
97	
98	    /**
99	     * What the screen would show if the grade had the percent on every date, changing nothing: of the OPEN and PENDING
100	     * claims whose person had the grade on the claim's date, how many would show a different due, and the sum of each
101	     * new due minus its current one (an n/a due counting as 0.00). A claim bound by a statement keeps its stated due.
102	     */
103	    public RatePreview preview(String sheetId, String grade, BigDecimal pct) {
104	        Sheet sheet = sheets.findById(sheetId).orElse(null);
105	        List<Rate> sheetRates = rates.findBySheetIdOrderByGradeAscFromDateAscIdAsc(sheetId);
106	        List<Rate> candidate = new ArrayList<>(sheetRates.stream().filter(r -> !r.getGrade().equals(grade)).toList());
107	        candidate.add(new Rate(sheetId, grade, null, pct));
108	        Map<Long, Person> byId = new LinkedHashMap<>();
109	        for (Person person : people.findBySheetIdOrderByIdAsc(sheetId)) {
110	            byId.put(person.getId(), person);
111	        }
112	        int count = 0;
113	        BigDecimal diff = zero();
114	        for (Claim claim : claims.findBySheetIdOrderByIdDesc(sheetId)) {
115	            Person person = byId.get(claim.getPersonId());
116	            if (person == null || !claim.getStatus().isOpen() || !grade.equals(person.gradeOn(claim.getDate()))) {
117	                continue;
118	            }
119	            BigDecimal now = dueOf(sheet, sheetRates, person, claim).map(RollupService::cents).orElse(null);
120	            BigDecimal then = dueOf(sheet, candidate, person, claim).map(RollupService::cents).orElse(null);
121	            if (Objects.equals(now, then)) {
122	                continue;
123	            }
124	            count++;
125	            diff = diff.add(then == null ? zero() : then).subtract(now == null ? zero() : now);
126	        }
127	        return new RatePreview(count, shown(diff));
128	    }
129	
130	    private static BigDecimal cents(BigDecimal value) {
131	        return value.setScale(2, RoundingMode.HALF_EVEN);
132	    }
133	
134	    /** The figures added up, leaving out the single highest and the single lowest when there are three or more. */
135	    private static BigDecimal trimmedSum(List<BigDecimal> figures) {
136	        List<BigDecimal> kept = new ArrayList<>(figures);
137	        if (kept.size() >= 3) {
138	            kept.sort(null);
139	            kept = kept.subList(1, kept.size() - 1);
140	        }
141	        return kept.stream().reduce(zero(), BigDecimal::add);
142	    }
143	
144	    /**
145	     * Each person's due-total of the dates from and to, both inclusive, by person id for every person on the sheet, as
146	     * the screen shows a person's for a period: the dues as shown now of their claims due by a date in them that were OPEN,
147	     * PENDING or SETTLED at the end of the to-date by their status log, skipping those with no due and the open ones a
148	     * hold of theirs leaves out; 0.00 with none.
149	     */
150	    public Map<Long, BigDecimal> dueTotalsBetween(String sheetId, LocalDate from, LocalDate to) {
151	        Sheet sheet = sheets.findById(sheetId).orElse(null);
152	        LocalDate today = sheet == null ? null : sheet.getToday();
153	        List<Rate> sheetRates = rates.findBySheetIdOrderByGradeAscFromDateAscIdAsc(sheetId);
154	        Map<Long, Person> byId = new LinkedHashMap<>();
155	        Map<Long, BigDecimal> totals = new LinkedHashMap<>();
156	        for (Person person : people.findBySheetIdOrderByIdAsc(sheetId)) {
157	            byId.put(person.getId(), person);
158	            totals.put(person.getId(), zero());
159	        }
160	        Map<Long, List<ClaimLog>> logOf = new LinkedHashMap<>();
161	        for (ClaimLog line : logs.findBySheetIdOrderByIdAsc(sheetId)) {
162	            logOf.computeIfAbsent(line.getClaimId(), id -> new ArrayList<>()).add(line);
163	        }
164	        for (Claim claim : claims.findBySheetIdOrderByIdDesc(sheetId)) {
165	            Person person = byId.get(claim.getPersonId());
166	            ClaimStatus status = statusOn(claim, logOf.getOrDefault(claim.getId(), List.of()), to);
167	            if (person == null || !person.countsAsOf(claim, status, today) || claim.getDueBy().isBefore(from)
168	                    || claim.getDueBy().isAfter(to)) {
169	                continue;
170	            }
171	            dueOf(sheet, sheetRates, person, claim).ifPresent(due -> totals.merge(person.getId(), due, BigDecimal::add));
172	        }
173	        totals.replaceAll((id, total) -> total.setScale(2, RoundingMode.HALF_EVEN));
174	        return totals;
175	    }
176	
177	    /**
178	     * Record, once the transaction commits, a ROLLUP line for each person whose figures moved since the snapshot (a
179	     * person new since then counting as moved), then a TOTALS line when any of the sheet's three totals moved.
180	     */
181	    public void recordChanges(String sheetId, String user, Snapshot before) {
182	        Snapshot after = snapshot(sheetId);
183	        for (Map.Entry<Long, Figures> entry : after.people().entrySet()) {
184	            Figures was = before.people().get(entry.getKey());
185	            Figures now = entry.getValue();
186	            if (was != null && was.claimed().equals(now.claimed()) && was.dueTotal().equals(now.dueTotal())
187	                    && was.overdueTotal().equals(now.overdueTotal())) {
188	                continue;
189	            }
190	            audit.recordOnCommit("ROLLUP sheet=" + sheetId + " by=" + user + " person=" + now.name()
191	                    + " claimed=" + now.claimed() + " due-total=" + now.dueTotal()
192	                    + " overdue-total=" + now.overdueTotal());
193	        }
194	        if (!Objects.equals(before.claimedTotal(), after.claimedTotal())
195	                || !Objects.equals(before.dueTotal(), after.dueTotal())
196	                || !Objects.equals(before.overdueTotal(), after.overdueTotal())) {
197	            audit.recordOnCommit("TOTALS sheet=" + sheetId + " by=" + user + " claimed-total=" + after.claimedTotal()
198	                    + " due-total=" + after.dueTotal() + " overdue-total=" + after.overdueTotal());
199	        }
200	    }
201	
202	    /**
203	     * As on the screen: the settled due, else the figure (the stated due, else the amount at the rate on the claim's
204	     * date, rounded as the sheet's policy date has the claim round) with the late charge of an overdue claim added on
205	     * top, raised last to the floor in force on the claim's date; a correction has neither floor nor late charge.
206	     */
207	    private static Optional<BigDecimal> dueOf(Sheet sheet, List<Rate> sheetRates, Person person, Claim claim) {
208	        if (claim.getSettledDue() != null) {
209	            return Optional.of(claim.getSettledDue());
210	        }
211	        Optional<BigDecimal> figure = claim.isBound() ? Optional.ofNullable(claim.getStatedDue())
212	                : rateOn(sheetRates, person.gradeOn(claim.getDate()), claim.getDate())
213	                        .map(Rate::getPct)
214	                        .map(pct -> sheet == null
215	                                ? claim.getAmount().multiply(pct).movePointLeft(2).setScale(2, RoundingMode.HALF_EVEN)
216	                                : sheet.rateStep(claim.getAmount(), pct, claim.getRoundingDate()));
217	        return sheet == null || claim.isCorrection() ? figure
218	                : figure.map(f -> sheet.floored(sheet.withLateCharge(f, claim.getStatus().isOpen(),
219	                        sheet.overdueBy(claim.getDueBy(), person.gradeOn(claim.getDate()), claim.getDate()),
220	                        claim.getDate()), claim.getDate()));
221	    }
222	
223	    /**
224	     * The status the claim had at the end of the date by its log (oldest first): its last line logged on or before the
225	     * date; null when it has lines but none by then. With no log at all, its status now.
226	     */
227	    private static ClaimStatus statusOn(Claim claim, List<ClaimLog> log, LocalDate date) {
228	        if (log.isEmpty()) {
229	            return claim.getStatus();
230	        }
231	        ClaimStatus found = null;
232	        for (ClaimLog line : log) {
233	            if (!line.getDate().isAfter(date)) {
234	                found = line.getStatus();
235	            }
236	        }
237	        return found;
238	    }
239	
240	    /**
241	     * As on the screen: an OPEN or PENDING claim whose due-by, plus the grace days its person's grade has on its date,
242	     * is before the sheet's today.
243	     */
244	    private static boolean isOverdue(Sheet sheet, Person person, Claim claim, LocalDate today) {
245	        return claim.getStatus().isOpen() && today != null && claim.getDueBy() != null
246	                && sheet.overdueBy(claim.getDueBy(), person.gradeOn(claim.getDate()), claim.getDate()).isBefore(today);
247	    }
248	
249	    private static Optional<Rate> rateOn(List<Rate> sheetRates, String grade, LocalDate date) {
250	        return sheetRates.stream()
251	                .filter(r -> r.getGrade().equals(grade))
252	                .filter(r -> r.getFromDate() == null || !r.getFromDate().isAfter(date))
253	                .max(Comparator.comparing(Rate::getFromDate, Comparator.nullsFirst(Comparator.naturalOrder())))
254	                .filter(r -> r.appliesOn(date));
255	    }
256	
257	    private static BigDecimal zero() {
258	        return BigDecimal.ZERO.setScale(2);
259	    }
260	
261	    private static String shown(BigDecimal value) {
262	        return value.setScale(2, RoundingMode.HALF_EVEN).toPlainString();
263	    }
264	}
