package net.officefloor.hq.app.statement;
/**
 * Takes statements of people. A statement records the person's due-total and binds each of their counting
 * claims to the due it shows then; their other claims are left unbound, so their dues are live again.
 */
@Service
public class StatementService {
    private final StatementRepository statements;
    private final PersonRepository people;
    private final ClaimRepository claims;
    private final ClaimLogRepository claimLogs;
    private final RateService rates;
    private final SheetService sheets;
    private final Audit audit;
    private final RollupService rollup;
    private final RoleService roles;
    public StatementService(StatementRepository statements, PersonRepository people, ClaimRepository claims,
            ClaimLogRepository claimLogs, RateService rates, SheetService sheets, Audit audit, RollupService rollup,
            RoleService roles) {
        this.roles = roles;
        this.claimLogs = claimLogs;
        this.statements = statements;
        this.people = people;
        this.claims = claims;
        this.rates = rates;
        this.sheets = sheets;
        this.audit = audit;
        this.rollup = rollup;
    }
    /** Each person's statement summary on the sheet, by person id; a person with none is missing. */
    public Map<Long, StatementSummary> summaries(String sheetId) {
        Map<Long, StatementSummary> by = new HashMap<>();
        for (Statement s : statements.findBySheetIdOrderByIdAsc(sheetId)) {
            by.put(s.getPersonId(), by.getOrDefault(s.getPersonId(), StatementSummary.NONE).then(s));
        }
        return by;
    }
    public StatementSummary summary(String sheetId, Long personId) {
        StatementSummary summary = StatementSummary.NONE;
        for (Statement s : statements.findBySheetIdAndPersonIdOrderByIdAsc(sheetId, personId)) {
            summary = summary.then(s);
        }
        return summary;
    }
    /**
     * Take a statement of the person on the sheet's today, or as of an earlier date ({@code asOf}, null: today);
     * refused for a date after the sheet's today, or before the person was added.
     */
    @Transactional
    public Person take(String sheetId, String user, Long personId, LocalDate asOf) {
        Person person = people.findForUpdate(personId, sheetId)
                .orElseThrow(() -> new PersonNotFoundException(sheetId, personId));
        Sheet sheet = sheets.get(sheetId);
        LocalDate today = sheet.getToday();
        if (asOf == null) {
            return take(sheet, user, person);
        }
        if (asOf.isAfter(today)) {
            throw new StatementDateException(person.getName(), asOf, "it is after the sheet's today " + today);
        }
        if (!person.addedBy(asOf)) {
            throw new StatementDateException(person.getName(), asOf, "the person was not on the sheet then");
        }
        return takeAsOf(sheet, user, person, asOf);
    }
    private Person take(Sheet sheet, String user, Person person) {
        String sheetId = sheet.getId();
        Long personId = person.getId();
        RollupService.Snapshot before = rollup.snapshot(sheetId);
        LocalDate today = sheet.getToday();
        List<Claim> theirs = claims.findBySheetIdAndPersonIdOrderByIdAsc(sheetId, personId);
        // As on the screen: n/a when the grade in force today has no rate today, unless a counting claim has a fixed due
        // or a due on or before today.
        boolean anyDue = rates.rateOn(sheetId, person.gradeOn(today), today).isPresent();
        BigDecimal total = BigDecimal.ZERO.setScale(2);
        int counted = 0;
        for (Claim claim : theirs) {
            if (!person.counts(claim, today)) {
                claim.setStated(false, null);
                continue;
            }
            counted++;
            if (claim.getSettledDue() != null || claim.getBoundDue() != null) {
                anyDue = true;
            }
            // The statement binds the rate figure under the claim's due; its late charge keeps following the sheet's
            // today, and the floor is applied last.
            BigDecimal figure = figureOf(sheetId, person, claim).orElse(null);
            BigDecimal due = claim.getSettledDue() != null || claim.isCorrection() ? figure
                    : sheet.floored(sheet.withLateCharge(figure, claim.getStatus().isOpen(),
                            sheet.overdueBy(claim.getDueBy(), person.gradeOn(claim.getDate()), claim.getDate()),
                            claim.getDate()), claim.getDate());
            if (due != null) {
                total = total.add(due);
                // A due under a grade the person had on an earlier date counts too.
                if (!claim.getDate().isAfter(today)) {
                    anyDue = true;
                }
            }
            claim.setStated(true, figure);
        }
        claims.saveAllAndFlush(theirs);
        String dueTotal = anyDue ? sheet.capped(total).toPlainString() : "n/a";
        statements.saveAndFlush(new Statement(sheetId, personId, today, today, dueTotal, counted));
        audit.recordOnCommit("STATEMENT sheet=" + sheetId + " by=" + user + " name=" + person.getName()
                + " due-total=" + dueTotal + " claims=" + counted);
        rollup.recordChanges(sheetId, user, before);
        return person;
    }
    /**
     * A statement as of an earlier date: the person's claims that counted at the end of it are bound to their figures
     * as they stood then, counting only the changes made while the sheet's today was on or before it, and with that
     * date standing in for the sheet's today in every figure. Every other claim of theirs is left unbound.
     */
    private Person takeAsOf(Sheet sheet, String user, Person person, LocalDate asOf) {
        String sheetId = sheet.getId();
        Long personId = person.getId();
        RollupService.Snapshot before = rollup.snapshot(sheetId);
        List<Claim> theirs = claims.findBySheetIdAndPersonIdOrderByIdAsc(sheetId, personId);
        // The claims' bindings stood then only when their last statement was taken by then.
        List<Statement> taken = statements.findBySheetIdAndPersonIdOrderByIdAsc(sheetId, personId);
        boolean bindingsStood = taken.isEmpty() || taken.get(taken.size() - 1).madeBy(asOf);
        boolean anyDue = rates.rateAsOf(sheetId, person.gradeOn(asOf), asOf, asOf).isPresent();
        BigDecimal total = BigDecimal.ZERO.setScale(2);
        int counted = 0;
        for (Claim claim : theirs) {
            ClaimStatus status = statusAsOf(claim, asOf);
            boolean bound = bindingsStood && claim.isStated() && status != ClaimStatus.PENDING;
            boolean counts = status != null && status.counts()
                    && !(status.isOpen() && !bound
                            && (person.heldAsOf(claim.getDate(), asOf) || person.retiredAsOf(asOf)))
                    && !(status == ClaimStatus.OPEN && claim.getDeferredUntil() != null
                            && asOf.isBefore(claim.getDeferredUntil()));
            if (!counts) {
                claim.setStated(false, null);
                continue;
            }
            counted++;
            BigDecimal settled = status == ClaimStatus.SETTLED ? claim.getSettledDue() : null;
            if (settled != null || (bound && claim.getStatedDue() != null)) {
                anyDue = true;
            }
            BigDecimal figure = settled != null ? settled
                    : bound ? claim.getStatedDue()
                    : rates.rateAsOf(sheetId, person.gradeOn(claim.getDate()), claim.getDate(), asOf)
                            .map(pct -> sheet.rateStep(claim.getAmount(), pct, claim.getRoundingDate(), asOf))
                            .orElse(null);
            BigDecimal due = settled != null || claim.isCorrection() ? figure
                    : sheet.floored(sheet.withLateCharge(figure, status.isOpen(),
                            sheet.overdueBy(claim.getDueBy(), person.gradeOn(claim.getDate()), claim.getDate()),
                            claim.getDate(), asOf), claim.getDate());
            if (due != null) {
                total = total.add(due);
                if (!claim.getDate().isAfter(asOf)) {
                    anyDue = true;
                }
            }
            claim.setStated(true, figure);
        }
        claims.saveAllAndFlush(theirs);
        String dueTotal = anyDue ? sheet.capped(total, asOf).toPlainString() : "n/a";
        statements.saveAndFlush(new Statement(sheetId, personId, asOf, sheet.getToday(), dueTotal, counted));
        audit.recordOnCommit("STATEMENT sheet=" + sheetId + " by=" + user + " name=" + person.getName()
                + " due-total=" + dueTotal + " claims=" + counted + " asof=" + asOf);
        rollup.recordChanges(sheetId, user, before);
        return person;
    }
    /** The status the claim had at the end of the date: its last status logged on or before it; null with none. */
    private ClaimStatus statusAsOf(Claim claim, LocalDate asOf) {
        ClaimStatus status = null;
        for (ClaimLog log : claimLogs.findByClaimIdOrderByIdAsc(claim.getId())) {
            if (!log.getDate().isAfter(asOf)) {
                status = log.getStatus();
            }
        }
        return status;
    }
    /**
     * A steward cancels the person's last statement: it is removed, so the statement before it (if any) is the last,
     * and the claims it bound are live again; a figure an earlier statement bound them to is not restored. Refused
     * for anyone else, and for a person with no statement.
     */
    @Transactional
    public Person cancelLast(String sheetId, String user, Long personId) {
        Person person = people.findForUpdate(personId, sheetId)
                .orElseThrow(() -> new PersonNotFoundException(sheetId, personId));
        if (roles.roleOf(sheetId, user) != Role.STEWARD) {
            throw new StatementCancelForbiddenException(sheetId, user);
        }
        List<Statement> theirs = statements.findBySheetIdAndPersonIdOrderByIdAsc(sheetId, personId);
        if (theirs.isEmpty()) {
            throw new NoStatementException(sheetId, personId);
        }
        Statement last = theirs.get(theirs.size() - 1);
        RollupService.Snapshot before = rollup.snapshot(sheetId);
        List<Claim> bound = claims.findBySheetIdAndPersonIdOrderByIdAsc(sheetId, personId);
        for (Claim claim : bound) {
            claim.setStated(false, null);
        }
        claims.saveAllAndFlush(bound);
        statements.delete(last);
        statements.flush();
        audit.recordOnCommit("STATEMENT_CANCELLED sheet=" + sheetId + " by=" + user + " name=" + person.getName()
                + " due-total=" + last.getDueTotal());
        rollup.recordChanges(sheetId, user, before);
        return person;
    }
    /**
     * The figure under the claim's due: the due fixed when it was settled, else the one its last statement bound it
     * to, else its amount times its grade's rate on its date (no floor); empty when it has none (n/a).
     */
    private Optional<BigDecimal> figureOf(String sheetId, Person person, Claim claim) {
        if (claim.getSettledDue() != null) {
            return Optional.of(claim.getSettledDue());
        }
        if (claim.isBound()) {
            return Optional.ofNullable(claim.getStatedDue());
        }
        return rates.rateOn(sheetId, person.gradeOn(claim.getDate()), claim.getDate())
                .map(Rate::getPct)
                .map(pct -> sheets.get(sheetId).rateStep(claim.getAmount(), pct, claim.getRoundingDate()));
    }
}
package net.officefloor.hq.app.rate;
/**
 * A rate for a grade on a sheet: a percent with two decimals, in force from its from-date (or from the
 * beginning of time when it has none) until the grade's next later-dated rate, and only through its to-date
 * when it has one.
 */
@Entity
@Table(name = "rate")
public class Rate {
    @Id
    @GeneratedValue(strategy = GenerationType.IDENTITY)
    private Long id;
    @Column(name = "sheet_id", nullable = false)
    private String sheetId;
    @Column(name = "grade", nullable = false)
    private String grade;
    @Column(name = "pct", nullable = false, precision = 5, scale = 2)
    private BigDecimal pct;
    /** The first day the rate applies; null when it applies from the beginning of time. */
    @Column(name = "from_date")
    private LocalDate fromDate;
    /** The last day the rate applies; null when it applies until the grade's next later-dated rate. */
    @Column(name = "to_date")
    private LocalDate toDate;
    protected Rate() {
    }
    public Rate(String sheetId, String grade, LocalDate fromDate, BigDecimal pct) {
        this.sheetId = sheetId;
        this.grade = grade;
        this.fromDate = fromDate;
        this.pct = pct;
    }
    public Long getId() {
        return id;
    }
    public String getSheetId() {
        return sheetId;
    }
    public String getGrade() {
        return grade;
    }
    public LocalDate getFromDate() {
        return fromDate;
    }
    public LocalDate getToDate() {
        return toDate;
    }
    public void setToDate(LocalDate toDate) {
        this.toDate = toDate;
    }
    /** Whether the rate applies on the date, given it is the grade's latest-dated rate on or before it. */
    public boolean appliesOn(LocalDate date) {
        return toDate == null || !date.isAfter(toDate);
    }
    public BigDecimal getPct() {
        return pct;
    }
    public void setPct(BigDecimal pct) {
        this.pct = pct;
    }
}
package net.officefloor.hq.app.rate;
/** Keeps the rates for each grade on a sheet, each in force from its from-date. */
@Service
public class RateService {
    private final RateRepository rates;
    private final RateLogRepository logs;
    private final SheetRepository sheets;
    private final Audit audit;
    private final RollupService rollup;
    public RateService(RateRepository rates, RateLogRepository logs, SheetRepository sheets, Audit audit,
            RollupService rollup) {
        this.rates = rates;
        this.logs = logs;
        this.sheets = sheets;
        this.audit = audit;
        this.rollup = rollup;
    }
    public List<Rate> list(String sheetId) {
        return rates.findBySheetIdOrderByGradeAscFromDateAscIdAsc(sheetId);
    }
    /**
     * The grade's rate in force on the date: the one with the latest from-date on or before it, an
     * undated rate counting as from the beginning of time. Empty when the date is before every rate, or
     * after that rate's to-date.
     */
    public Optional<Rate> rateOn(String sheetId, String grade, LocalDate date) {
        return rates.findBySheetIdAndGrade(sheetId, grade).stream()
                .filter(r -> r.getFromDate() == null || !r.getFromDate().isAfter(date))
                .max(Comparator.comparing(Rate::getFromDate, Comparator.nullsFirst(Comparator.naturalOrder())))
                .filter(r -> r.appliesOn(date));
    }
    /**
     * The grade's rate percent in force on the date as the rates stood at the end of {@code asOf}: each from-date's
     * last setting made while the sheet's today was on or before it (a rate set before settings were logged counts as
     * it is now). Empty when the grade had no rate in force on the date then.
     */
    public Optional<BigDecimal> rateAsOf(String sheetId, String grade, LocalDate date, LocalDate asOf) {
        List<Rate> now = rates.findBySheetIdAndGrade(sheetId, grade);
        List<RateLog> set = logs.findBySheetIdAndGradeOrderByIdAsc(sheetId, grade);
        Map<LocalDate, RateLog> then = new LinkedHashMap<>();
        for (RateLog log : set) {
            if (!log.getSetOn().isAfter(asOf)) {
                then.put(log.getFromDate(), log);
            }
        }
        List<Rate> stood = new ArrayList<>();
        for (Rate rate : now) {
            boolean logged = set.stream().anyMatch(l -> Objects.equals(l.getFromDate(), rate.getFromDate()));
            if (!logged) {
                stood.add(rate);
            }
        }
        for (RateLog log : then.values()) {
            Rate rate = new Rate(sheetId, grade, log.getFromDate(), log.getPct());
            rate.setToDate(log.getToDate());
            stood.add(rate);
        }
        return stood.stream()
                .filter(r -> r.getFromDate() == null || !r.getFromDate().isAfter(date))
                .max(Comparator.comparing(Rate::getFromDate, Comparator.nullsFirst(Comparator.naturalOrder())))
                .filter(r -> r.appliesOn(date))
                .map(Rate::getPct);
    }
    /** What the grade having the percent on every date would change on the sheet; nothing is saved. */
    @Transactional(readOnly = true)
    public RollupService.RatePreview preview(String sheetId, String grade, BigDecimal pct) {
        if (!sheets.existsById(sheetId)) {
            throw new SheetNotFoundException(sheetId);
        }
        return rollup.preview(sheetId, grade, pct);
    }
    /**
     * Set the grade's rate from the from-date (null: from the beginning of time) through the to-date (null: no
     * end), replacing the one it had; a to-date before the from-date is refused.
     */
    @Transactional
    public Rate set(String sheetId, String user, String grade, LocalDate fromDate, LocalDate toDate, BigDecimal pct) {
        if (!sheets.existsById(sheetId)) {
            throw new SheetNotFoundException(sheetId);
        }
        if (fromDate != null && toDate != null && toDate.isBefore(fromDate)) {
            throw new RateDatesException(fromDate, toDate);
        }
        RollupService.Snapshot before = rollup.snapshot(sheetId);
        Rate rate = rates.findBySheetIdAndGradeAndFromDate(sheetId, grade, fromDate).orElse(null);
        if (rate == null) {
            rate = new Rate(sheetId, grade, fromDate, pct);
        } else {
            rate.setPct(pct);
        }
        rate.setToDate(toDate);
        Rate saved;
        try {
            saved = rates.saveAndFlush(rate);
        } catch (DataIntegrityViolationException e) {
            throw new RateTakenException(sheetId, grade);
        }
        logs.save(new RateLog(saved, sheets.findById(sheetId).orElseThrow().getToday()));
        audit.recordOnCommit("RATE_SET sheet=" + sheetId + " by=" + user + " grade=" + saved.getGrade()
                + " rate=" + saved.getPct().setScale(2, RoundingMode.UNNECESSARY).toPlainString()
                + (saved.getFromDate() == null ? "" : " from=" + saved.getFromDate())
                + (saved.getToDate() == null ? "" : " to=" + saved.getToDate()));
        rollup.recordChanges(sheetId, user, before);
        return saved;
    }
}

